package net.minecraft.client.gui;import net.minecraft.network.chat.Component;import org.joml.Matrix4f;import net.minecraft.client.renderer.MultiBufferSource;import proof.Trace;
public class Font {public int lineHeight=9;public enum DisplayMode{NORMAL}public int width(String s){return s.length()*6;}public int width(Component s){return width(s.toString());}public void drawInBatch(Component t,float x,float y,int c,boolean shadow,Matrix4f m,MultiBufferSource b,DisplayMode mode,int background,int light){Trace.add("label:"+t+":"+Trace.f(x)+":"+Trace.f(y)+":"+c+":"+shadow+":"+m+":"+mode+":"+background+":"+light);}}
